-- =============================================================================
-- 0047_pooja_modes_table.sql
--
-- GENERATED by scripts/build-pooja-modes-table.mjs. Do not hand-edit.
--
-- A pooja's modes become data. pooja_steps.modes has been a free text[] since
-- 0009, but the three values it held -- main, punar, udvasana -- were hardcoded
-- in PoojaViewer along with their labels, their Tamil and their hints. Fine
-- while every pooja with modes was a multi-day observance.
--
-- Sandhyavandanam is not. Its modes are three SITTINGS: praatah, maadhyaahnika,
-- saayam. Same machinery, different words, and the picker cannot know them
-- because they live in a .tsx file.
--
-- A TABLE RATHER THAN A SECOND HARDCODED MAP, because these are content: they
-- are bilingual, they need the same Tamil review as every other string, and the
-- next rite will bring its own. A map in the component puts Tamil somewhere no
-- proofread gate can see it, which is how step_title_ta came to be empty on
-- eighteen rows before 0006.
--
-- seq is stored because the order is neither alphabetical nor insertion order:
-- main before punar before udvasana, morning before noon before evening. A
-- picker that sorted for itself would put maadhyaahnika first.
-- =============================================================================

begin;

create table if not exists public.pooja_modes (
  pooja_id   text not null references public.poojas(id) on delete cascade,
  mode       text not null,
  seq        integer not null,
  label_en   text not null,
  label_ta   text not null,
  hint_en    text not null,
  hint_ta    text not null,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now(),
  primary key (pooja_id, mode)
);

comment on table public.pooja_modes is
  'The modes a pooja offers, with their labels. A mode string here must match the values used in pooja_steps.modes. seq orders the picker.';

-- Read-only through the API like every other content table. Same reasoning as
-- 0038: the app only reads, and migrations run as the owner, so enable rather
-- than force.
alter table public.pooja_modes enable row level security;
do $$ begin
  if not exists (select 1 from pg_policies where schemaname = 'public'
                  and tablename = 'pooja_modes' and policyname = 'public read pooja_modes') then
    create policy "public read pooja_modes" on public.pooja_modes for select using (true);
  end if;
end $$;

