-- --- assert ------------------------------------------------------------------
do $$
declare n int;
begin
  select count(*) into n from public.pooja_modes where pooja_id = 'ganesha_standard';
  if n <> 3 then raise exception 'ganesha_standard has % modes, expected 3', n; end if;
  select count(*) into n from public.pooja_modes where pooja_id = 'varalakshmi_vratham';
  if n <> 3 then raise exception 'varalakshmi_vratham has % modes, expected 3', n; end if;
  select count(*) into n from public.pooja_modes where pooja_id = 'nitya_panchayatana';
  if n <> 1 then raise exception 'nitya_panchayatana has % modes, expected 1', n; end if;
  select count(*) into n from public.pooja_modes where pooja_id = 'sandhyavandanam';
  if n <> 3 then raise exception 'sandhyavandanam has % modes, expected 3', n; end if;

  -- Every mode a STEP claims must be declared here, or the picker will filter
  -- on a value it cannot name and the step will be unreachable. This is the
  -- assertion that makes the table worth having.
  select count(*) into n from (
    select distinct s.pooja_id, unnest(s.modes) as mode from public.pooja_steps s
  ) claimed
  where not exists (
    select 1 from public.pooja_modes m
     where m.pooja_id = claimed.pooja_id and m.mode = claimed.mode
  );
  if n > 0 then raise exception '% step mode(s) are not declared in pooja_modes', n; end if;

  -- ...and nothing is declared that no step uses, which would put a dead button
  -- on the preparation screen.
  select count(*) into n from public.pooja_modes m
   where exists (select 1 from public.pooja_steps s where s.pooja_id = m.pooja_id)
     and not exists (
       select 1 from public.pooja_steps s
        where s.pooja_id = m.pooja_id and m.mode = any(s.modes)
     );
  if n > 0 then raise exception '% declared mode(s) have no steps', n; end if;
end $$;


-- Carriage returns, from pasting this file into a browser SQL editor. See
-- scripts/_migration.mjs.
do $$
declare
  r record;
  n bigint;
begin
  for r in
    select c.table_name, c.column_name
      from information_schema.columns c
      join information_schema.tables t
        on t.table_schema = c.table_schema and t.table_name = c.table_name
     where c.table_schema = 'public'
       and t.table_type = 'BASE TABLE'
       and c.data_type in ('text', 'character varying', 'character')
  loop
    execute format(
      'update public.%I set %I = replace(%I, chr(13), %L)'
      || ' where position(chr(13) in %I) > 0',
      r.table_name, r.column_name, r.column_name, '', r.column_name
    );
    get diagnostics n = row_count;
    if n > 0 then
      raise notice 'stripped CR from % row(s) of %.%', n, r.table_name, r.column_name;
    end if;
  end loop;
end $$;

